pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // Ensure input lengths are consistent
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Prepare the output vector
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        let v = match (c1, c2) {
            (true, true) => {
                // both conditions true: integer average
                (vals_1[i] + vals_2[i]) / 2
            }
            (true, false) => {
                // only first condition is true
                vals_1[i]
            }
            (false, true) => {
                // only second condition is true
                vals_2[i]
            }
            (false, false) => {
                // As per the problem statement, this should never happen
                unreachable!("At least one condition must be true at each index");
            }
        };
        avgs.push(v);
    }
}